package com.quincaisoft.platformcontrol.web;import com.quincaisoft.platformcontrol.api.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import java.util.*;
@RestController @RequestMapping("/admin/onboarding") public class PlatformController{private final PlatformService service;public PlatformController(PlatformService service){this.service=service;}@GetMapping @PreAuthorize("hasAuthority('SCOPE_platform:tenants:read')") public List<PlatformService.Item> list(){return service.list();}@GetMapping("/{id}") @PreAuthorize("hasAuthority('SCOPE_platform:tenants:read')") public PlatformService.Item get(@PathVariable UUID id){return service.get(id);}@PostMapping @PreAuthorize("hasAuthority('SCOPE_platform:tenants:write')")public PlatformService.Item request(@RequestHeader("Idempotency-Key")UUID operation,@RequestHeader("X-Request-ID")UUID request,@RequestBody PlatformService.Request input){if(!operation.equals(input.operationId()))throw new IllegalArgumentException("Operation mismatch");return service.request(input);}@PostMapping("/{id}/approve") @PreAuthorize("hasAuthority('SCOPE_platform:tenants:approve')")public PlatformService.Item approve(@PathVariable UUID id,@RequestHeader("Idempotency-Key")UUID operation,@RequestHeader("X-Request-ID")UUID request,@RequestBody PlatformService.Review input){if(!operation.equals(input.operationId()))throw new IllegalArgumentException("Operation mismatch");return service.approve(id,input);}}
